                apiRequestOptions.HeaderParameters.Add("if-match", ApiUtils.ParameterToString(Configuration, ifMatch)); // header parameter
            }
            apiRequestOptions.Data = playerUpdateRequest;

            apiRequestOptions.Operation = "LobbyApi.UpdatePlayer";
            // make the HTTP request
            return await this.Client.PostAsync<Model.Lobby>("/{lobbyId}/players/{playerId}", apiRequestOptions, this.Configuration, cancellationToken);
        }

    }
